export interface AuditPort {
  record(event: AuditEvent): Observable<void>;
}

export const AUDIT_PORT = new InjectionToken<AuditPort>('AUDIT_PORT');

@Injectable({ providedIn: 'root' })
export class HttpAuditAdapter implements AuditPort {
  private readonly http = inject(HttpClient);

  record(event: AuditEvent): Observable<void> {
    return this.http.post<void>('/api/audit', event);
  }
}

export const appConfig: ApplicationConfig = {
  providers: [
    { provide: AUDIT_PORT, useExisting: HttpAuditAdapter },
  ],
};

@Injectable({ providedIn: 'root' })
export class PaymentService {
  private readonly repository = inject(PaymentRepository);
  private readonly audit = inject(AUDIT_PORT);

  submit(command: PaymentCommand): Observable<PaymentResult> {
    return this.repository.submit(command).pipe(
      switchMap(result => this.audit.record({
        type: 'payment-submitted',
        commandId: command.id,
      }).pipe(map(() => result)))
    );
  }
}

