  private readonly refreshedOrder = signal<Order | null>(null);

  readonly viewOrder = computed(() => this.refreshedOrder() ?? this.order());
  readonly title = computed(() => `Order ${this.viewOrder().id}`);
  readonly total = computed(() => calculateTotal(this.viewOrder().lines));

  private readonly api = inject(OrderApi);

  refresh(): void {
    this.api.refresh(this.viewOrder().id).subscribe(order => {
      this.refreshedOrder.set(order);
    });
  }
}

@Component({
  selector: 'app-customer-search',
  template: `
    <input [value]="query()" (input)="query.set(($any($event.target)).value)" />

    @if (loading()) { <p>Searching…</p> }
    @for (customer of results(); track customer.id) {
      <button>{{ customer.name }}</button>
    }
  `,
})
export class CustomerSearchComponent {
  private readonly api = inject(CustomerApi);

  readonly query = signal('');
  private readonly query$ = toObservable(this.query);

  private readonly response = toSignal(
    this.query$.pipe(
      map(value => value.trim()),
      debounceTime(250),
      distinctUntilChanged(),
      switchMap(query => query.length < 2
        ? of({ loading: false, items: [] as Customer[] })
        : concat(
            of({ loading: true, items: [] as Customer[] }),
            this.api.search(query).pipe(
              map(items => ({ loading: false, items })),
              catchError(() => of({ loading: false, items: [] as Customer[] }))
            )
          )
      )
    ),
    { initialValue: { loading: false, items: [] as Customer[] } }
  );

  readonly loading = computed(() => this.response().loading);
  readonly results = computed(() => this.response().items);
}

readonly searchState$ = this.searchControl.valueChanges.pipe(
  startWith(this.searchControl.value),
  map(value => value.trim()),
  debounceTime(250),
  distinctUntilChanged(),
  switchMap(query => {
    if (query.length < 2) {
      return of({ status: 'idle' as const, items: [] as Customer[] });
    }

    return this.api.search(query).pipe(
      map(items => ({ status: 'success' as const, items })),
      startWith({ status: 'loading' as const, items: [] as Customer[] }),
      catchError(error => of({
        status: 'error' as const,
        items: [] as Customer[],
        message: getSafeMessage(error),
      }))
    );
  }),
  shareReplay({ bufferSize: 1, refCount: true })
);

