const RETRIED_AFTER_REFRESH = new HttpContextToken<boolean>(() => false);
const SKIP_AUTH = new HttpContextToken<boolean>(() => false);

export const authInterceptor: HttpInterceptorFn = (req, next) => {
  const session = inject(SessionService);

  if (req.context.get(SKIP_AUTH)) {
    return next(req);
  }

  const withToken = addBearerToken(req, session.accessToken());

  return next(withToken).pipe(
    catchError(error => {
      const canRefresh =
        error.status === 401 &&
        !req.context.get(RETRIED_AFTER_REFRESH);

      if (!canRefresh) {
        return throwError(() => error);
      }

      return session.refreshOnce().pipe(
        switchMap(newToken => next(
          addBearerToken(
            req.clone({
              context: req.context.set(RETRIED_AFTER_REFRESH, true),
            }),
            newToken
          )
        )),
        catchError(refreshError => {
          session.endSessionOnce();
          return throwError(() => refreshError);
        })
      );
    })
  );
};

function addBearerToken<T>(req: HttpRequest<T>, token: string | null): HttpRequest<T> {
  return token
    ? req.clone({ setHeaders: { Authorization: `Bearer ${token}` } })
    : req;
}

