@Injectable()
export class DashboardStore {
  private readonly socket = inject(DashboardSocket);
  private readonly _byId = signal<ReadonlyMap<string, WidgetState>>(new Map());

  readonly byId = this._byId.asReadonly();

  constructor() {
    this.socket.messages$.pipe(
      bufferTime(100),
      filter(batch => batch.length > 0),
      takeUntilDestroyed()
    ).subscribe(batch => {
      this._byId.update(current => {
        const next = new Map(current);
        for (const update of batch) {
          next.set(update.widgetId, reduceWidget(next.get(update.widgetId), update));
        }
        return next;
      });
    });
  }

  widget(id: () => string): Signal<WidgetState | undefined> {
    return computed(() => this._byId().get(id()));
  }
}

